mapper.sql:
WHERE 1 = 1

    AND LOWER(UNIV_NAME) LIKE '%' || LOWER(#{keyword}) || '%'


    AND SUBSCRIPTION_STATUS = #{subscriptionStatus}


    AND PLAN_ID = #{planId}

mapper.select:
SELECT M.MEMBER_ID, M.UNIV_ID, M.LOGIN_ID, M.MEMBER_NAME, M.ROLE, M.STATUS, M.CREATED_AT, M.LOGTIME_AT FROM MEMBER M WHERE M.ROLE = 'ADM' AND M.UNIV_ID IN
#{univId}
ORDER BY M.UNIV_ID, M.CREATED_AT, M.MEMBER_ID

